"""==============================================================================IOTEC107_AGENT_GOVERNANCE_ENGINE.py==============================================================================Governança Central dos AgentesVersão: 1.0=============================================================================="""from __future__ import annotationsimport sqlite3from pathlib import Pathfrom datetime import datetimeDATABASE = Path("iotec.db")class AgentGovernance:    def __init__(self):        self.conn = sqlite3.connect(DATABASE)        self.conn.row_factory = sqlite3.Row        self.create_table()    # ======================================================================    def create_table(self):        self.conn.execute("""        CREATE TABLE IF NOT EXISTS agent_governance(            id INTEGER PRIMARY KEY AUTOINCREMENT,            created_at TEXT,            mission_uuid TEXT,            agent_uuid TEXT,            action TEXT,            status TEXT,            details TEXT        )        """)        self.conn.commit()    # ======================================================================    def register_action(        self,        mission_uuid,        agent_uuid,        action,        status="OK",        details=""    ):        self.conn.execute("""        INSERT INTO agent_governance(            created_at,            mission_uuid,            agent_uuid,            action,            status,            details        )        VALUES(?,?,?,?,?,?)        """,(            datetime.utcnow().isoformat(),            mission_uuid,            agent_uuid,            action,            status,            details        ))        self.conn.commit()    # ======================================================================    def timeline(self, mission_uuid):        rows = self.conn.execute("""        SELECT *        FROM agent_governance        WHERE mission_uuid=?        ORDER BY id        """,(mission_uuid,)).fetchall()        return [dict(r) for r in rows]    # ======================================================================    def history(self):        rows = self.conn.execute("""        SELECT *        FROM agent_governance        ORDER BY id DESC        LIMIT 100        """).fetchall()        return [dict(r) for r in rows]# =============================================================================if __name__ == "__main__":    engine = AgentGovernance()    engine.register_action(        mission_uuid="MISSION-001",        agent_uuid="AG001",        action="MISSION_RECEIVED",        status="OK",        details="Missão recebida pelo CODEX"    )    engine.register_action(        mission_uuid="MISSION-001",        agent_uuid="AG001",        action="MODULE_CREATED",        status="OK",        details="Arquivo criado"    )    engine.register_action(        mission_uuid="MISSION-001",        agent_uuid="AG002",        action="EXECUTION_STARTED",        status="RUNNING",        details="OPENHANDS iniciou execução"    )    for item in engine.history():        print(item)